const {chromium}=require('./browser/node_modules/playwright');
(async()=>{const browser=await chromium.launch();const page=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=500)errors.push(r.status()+' '+r.url())});try{
for(const lang of ['ro','en','de']){await page.goto('http://127.0.0.1:4183/'+lang+'/collection');await page.waitForSelector('.product');const names=await page.locator('.product h3').allTextContents();if(names.length!==2)throw Error('Expected two products: '+names);console.log(lang,names);const images=await page.locator('.product-image img').evaluateAll(imgs=>imgs.map(i=>({src:i.src,loaded:i.complete&&i.naturalWidth===1536})));if(images.some(i=>!i.loaded)){await page.waitForFunction(()=>[...document.querySelectorAll('.product-image img')].every(i=>i.complete&&i.naturalWidth===1536));}}
await page.goto('http://127.0.0.1:4183/ro/');await page.waitForSelector('.product');await page.locator('[data-action=cookies]').click();await page.waitForFunction(()=>[...document.images].filter(i=>!i.loading||i.loading!=='lazy').every(i=>i.complete));await page.screenshot({path:'outputs/dracula-food/preview-desktop.png',fullPage:true});await page.locator('#collection').screenshot({path:'outputs/dracula-food/preview-produse.png'});
await page.locator('.product-image').nth(1).click();await page.waitForSelector('.detail-copy');console.log('DETAIL',await page.locator('h1').textContent());await page.locator('.detail-copy [data-action=add]').click();await page.waitForTimeout(300);if(await page.locator('.bag-count').textContent()!=='1')throw Error('Add to cart failed');await page.goto('http://127.0.0.1:4183/ro/bag');await page.waitForSelector('.bag-row');console.log('CART',await page.locator('.bag-row h3').textContent());await page.locator('[data-action=remove]').click();await page.waitForSelector('.empty');
await page.goto('http://127.0.0.1:4183/ro/collection');await page.waitForSelector('.product');await page.setViewportSize({width:390,height:844});await page.screenshot({path:'outputs/dracula-food/preview-produse-mobil.png',fullPage:true});const size=await page.evaluate(()=>[innerWidth,document.documentElement.scrollWidth]);if(size[0]!==size[1])throw Error('Mobile overflow');console.log('MOBILE',size,'ERRORS',errors);if(errors.length)throw Error(errors.join('\n'));
}finally{await browser.close();}})();
